parameters.jsCode:
// Parse WooCommerce webhook + Source-of-Truth filter.
// WC sends multiple event types; we care about: order.created, product.updated.
// SoT rule:
//   - order.created  → stock decrement event we propagate to Odoo
//   - product.updated with stock change   → IGNORE (Odoo is SoT for stock)
//   - product.updated with price/content  → propagate to Odoo for catalog mirror
const sync_event_id = JSON.parse(JSON.stringify($('Idempotency: WC Event').item.json)).id;
const raw = JSON.parse(JSON.stringify($('Webhook: WooCommerce').item.json));
const body = raw.body || raw;
const topic = (raw.headers && raw.headers['x-wc-webhook-topic']) || body._topic || 'unknown';

let field, action, sku, value, should_propagate, ignored_reason;

if (topic === 'order.created') {
  field = 'stock';
  action = 'decrement';
  // Order line items contain SKU + qty
  const items = (body.line_items || []).map(li => ({ sku: li.sku, qty: li.quantity }));
  return items.map(it => ({ json: {
    sync_event_id, source: 'woocommerce', target: 'odoo',
    field: 'stock', action: 'decrement',
    sku: it.sku, value: it.qty, should_propagate: !!it.sku, ignored_reason: it.sku ? null : 'no_sku'
  }}));
}

if (topic === 'product.updated') {
  sku = body.sku;
  // Determine which field changed by inspecting payload (in real life: WC sends full payload, we'd diff vs cache)
  // For showcase, route by payload hint. If stock changed, ignore (Odoo is SoT).
  if (body._stock_changed === true) {
    return [{ json: { sync_event_id, source: 'woocommerce', target: 'odoo',
      field: 'stock', action: 'set', sku, value: body.stock_quantity,
      should_propagate: false, ignored_reason: 'odoo_is_sot_for_stock' }}];
  }
  if (body._price_changed === true) {
    return [{ json: { sync_event_id, source: 'woocommerce', target: 'odoo',
      field: 'price', action: 'set', sku, value: body.regular_price,
      should_propagate: true, ignored_reason: null }}];
  }
  return [{ json: { sync_event_id, source: 'woocommerce', target: 'odoo',
    field: 'unknown', action: 'noop', sku, value: null,
    should_propagate: false, ignored_reason: 'unsupported_field' }}];
}

return [{ json: { sync_event_id, source: 'woocommerce', target: 'odoo',
  field: null, action: null, sku: null, value: null,
  should_propagate: false, ignored_reason: 'unsupported_topic:' + topic }}];

