parameters.jsCode:
// Parse Odoo webhook + Source-of-Truth filter (mirror of WC parse).
// Odoo Automation rules typically post: { event_id, model, operation, sku, field, value, ... }
// SoT: stock change in Odoo → propagate to WC. Price change in Odoo → IGNORE (WC is SoT for price).
const sync_event_id = JSON.parse(JSON.stringify($('Idempotency: Odoo Event').item.json)).id;
const raw = JSON.parse(JSON.stringify($('Webhook: Odoo').item.json));
const body = raw.body || raw;
const { sku, field, value, operation } = body;

let should_propagate = false, ignored_reason = null;

if (!sku) {
  ignored_reason = 'no_sku';
} else if (field === 'stock' || field === 'qty_available') {
  should_propagate = true;
} else if (field === 'price' || field === 'list_price') {
  ignored_reason = 'wc_is_sot_for_price';
} else {
  ignored_reason = 'unsupported_field:' + field;
}

return [{ json: {
  sync_event_id, source: 'odoo', target: 'woocommerce',
  field: field || null, action: operation || 'set', sku: sku || null, value,
  should_propagate, ignored_reason
}}];

// Reconciliation: compute drift between WooCommerce and Odoo per SKU.
// Drift threshold: any non-zero difference is reported. Auto-fix toggle via env.
const wc   = JSON.parse(JSON.stringify($('Recon: Fetch WC Products').item.json));
const odoo = JSON.parse(JSON.stringify($('Recon: Fetch Odoo Products').item.json));
const auto_fix = String($env.RECONCILIATION_AUTO_FIX || 'false').toLowerCase() === 'true';

const wcArr   = Array.isArray(wc) ? wc : (wc.data || []);
const odooArr = (odoo && odoo.result) ? odoo.result : (Array.isArray(odoo) ? odoo : []);

const wcBySku = {};
for (const p of wcArr) if (p.sku) wcBySku[p.sku] = { stock: Number(p.stock_quantity), price: parseFloat(p.regular_price || p.price) };

const odooBySku = {};
for (const p of odooArr) if (p.default_code) odooBySku[p.default_code] = { stock: Number(p.qty_available), price: parseFloat(p.list_price) };

const skus = new Set([...Object.keys(wcBySku), ...Object.keys(odooBySku)]);

const drift_items = [];
for (const sku of skus) {
  const w = wcBySku[sku];
  const o = odooBySku[sku];
  if (!w) { drift_items.push({ sku, kind: 'missing_in_wc', wc: null, odoo: o }); continue; }
  if (!o) { drift_items.push({ sku, kind: 'missing_in_odoo', wc: w, odoo: null }); continue; }
  if (w.stock !== o.stock) drift_items.push({ sku, kind: 'stock_drift', wc: w.stock, odoo: o.stock, diff: w.stock - o.stock });
  // Price drift only reported (WC is SoT, no auto-fix to Odoo)
  if (Math.abs((w.price || 0) - (o.price || 0)) > 0.01) drift_items.push({ sku, kind: 'price_drift', wc: w.price, odoo: o.price });
}

return [{ json: {
  run_started_at: new Date().toISOString(),
  total_skus_checked: skus.size,
  total_drift_items: drift_items.length,
  stock_drift_count: drift_items.filter(d => d.kind === 'stock_drift').length,
  price_drift_count: drift_items.filter(d => d.kind === 'price_drift').length,
  missing_count:     drift_items.filter(d => d.kind.startsWith('missing_')).length,
  auto_fix,
  drift_items
}}];
